<?php
declare(strict_types=1);require dirname(__DIR__).'/app/bootstrap.php';$user=require_permission('finance.view');\App\Core\Tenant::enforceActive((int)$user['tenant_id']);$t=(int)$user['tenant_id'];$scope=in_array($user['role_slug'],['psychologist','supervised'],true)?" AND (professional_id=:u OR patient_id IN (SELECT id FROM patients WHERE tenant_id=:t2 AND primary_professional_id=:u2))":'';$par=['t'=>$t];if($scope){$par+=['u'=>$user['id'],'t2'=>$t,'u2'=>$user['id']];}$st=db()->prepare("SELECT COALESCE(SUM(CASE WHEN type='income' AND status='paid' THEN amount ELSE 0 END),0) income,COALESCE(SUM(CASE WHEN type='expense' AND status='paid' THEN amount ELSE 0 END),0) expense,COALESCE(SUM(CASE WHEN type='income' AND status='pending' THEN amount ELSE 0 END),0) pending FROM financial_transactions WHERE tenant_id=:t AND YEAR(COALESCE(paid_at,due_date,created_at))=YEAR(CURDATE()) AND MONTH(COALESCE(paid_at,due_date,created_at))=MONTH(CURDATE()){$scope}");$st->execute($par);$tot=$st->fetch();$listScope=in_array($user['role_slug'],['psychologist','supervised'],true)?' AND (f.professional_id=:u OR p.primary_professional_id=:u2)':'';$lp=['t'=>$t];if($listScope)$lp+=['u'=>$user['id'],'u2'=>$user['id']];$st=db()->prepare("SELECT f.*,p.name patient_name FROM financial_transactions f LEFT JOIN patients p ON p.id=f.patient_id AND p.tenant_id=f.tenant_id WHERE f.tenant_id=:t{$listScope} ORDER BY f.created_at DESC LIMIT 200");$st->execute($lp);$items=$st->fetchAll();layout('Financeiro',function()use($tot,$items,$user){?><div class="page-head"><div><span class="eyebrow">Financeiro</span><h1>Faturamento e caixa</h1><p>Receitas, despesas, recibos e exportação para apoio fiscal.</p></div><div class="split-actions"><?php if(\App\Core\Rbac::allows((int)$user['id'],'finance.export')):?><a class="button ghost" href="<?=e(url('finance/export.php'))?>">Exportar CSV</a><?php endif?><?php if(\App\Core\Rbac::allows((int)$user['id'],'finance.manage')):?><a class="button" href="<?=e(url('finance/new.php'))?>">+ Lançamento</a><?php endif?></div></div><div class="kpi-grid"><div class="kpi"><small>Entradas pagas</small><strong data-private>R$ <?=number_format((float)$tot['income'],2,',','.')?></strong></div><div class="kpi"><small>Saídas pagas</small><strong data-private>R$ <?=number_format((float)$tot['expense'],2,',','.')?></strong></div><div class="kpi"><small>A receber</small><strong data-private>R$ <?=number_format((float)$tot['pending'],2,',','.')?></strong></div><div class="kpi"><small>Resultado</small><strong data-private>R$ <?=number_format((float)$tot['income']-(float)$tot['expense'],2,',','.')?></strong></div></div><div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Data</th><th>Descrição</th><th>Paciente</th><th>Tipo</th><th>Valor</th><th>Status</th><th>Ações</th></tr></thead><tbody><?php if(!$items):?><tr><td colspan="7" class="muted">Nenhum lançamento.</td></tr><?php endif?><?php foreach($items as $f):?><tr><td><?=e($f['due_date']?date('d/m/Y',strtotime($f['due_date'])):date('d/m/Y',strtotime($f['created_at'])))?></td><td><?=e($f['description'])?></td><td data-private><?=e($f['patient_name']?:'—')?></td><td><?=e($f['type']==='income'?'Entrada':'Saída')?></td><td data-private>R$ <?=number_format((float)$f['amount'],2,',','.')?></td><td><span class="status <?=e($f['status'])?>"><?=e($f['status'])?></span></td><td><div class="split-actions"><?php if($f['type']==='income'&&$f['status']==='paid'):?><a href="<?=e(url('finance/receipt.php?id='.$f['id']))?>">Recibo PDF</a><?php endif?><?php if(\App\Core\Rbac::allows((int)$user['id'],'finance.manage')&&$f['status']==='pending'):?><form method="post" action="<?=e(url('finance/status.php'))?>"><?=csrf_field()?><input type="hidden" name="id" value="<?=$f['id']?>"><button class="button ghost small" name="status" value="paid">Dar baixa</button></form><?php endif?></div></td></tr><?php endforeach?></tbody></table></div></div><?php },['active'=>'finance']);
